// Build responsive, profession-styled HTML report
let report = $json.output;
if (typeof report === 'string') {
  let clean = report.trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
  }
  try { report = JSON.parse(clean); } catch (e) { report = {}; }
}

const ctx = $('11. Profession Prompt Adapter').first().json;
const profession = ctx.profession;
const userName = ctx.userName;
const reportDate = report.reportDate || ctx.reportDate;
const totalEmails = typeof report.totalEmails === 'number' ? report.totalEmails : ctx.totalEmails;

const escapeHtml = (v) => (v == null ? '' : String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;'));
const safeArr = (v) => (Array.isArray(v) ? v : []);

const urgentEmails = safeArr(report.urgentEmails);
const importantEmails = safeArr(report.importantEmails);
const repliedEmails = safeArr(report.repliedEmails);
const otherEmails = safeArr(report.otherEmails);
const actionItems = safeArr(report.actionItems);
const overallSummary = report.overallSummary || (totalEmails === 0 ? 'No new emails received during this 24-hour reporting window.' : 'Email intelligence report synthesized by InboxIQ.');

let badgeTitle = 'Faculty Intelligence';
let themeGradient = 'linear-gradient(135deg, #111827 0%, #1e3a8a 100%)';
if (profession === 'student') {
  badgeTitle = 'Student Academic Pulse';
  themeGradient = 'linear-gradient(135deg, #064e3b 0%, #047857 100%)';
} else if (profession === 'others') {
  badgeTitle = 'Executive Intelligence';
  themeGradient = 'linear-gradient(135deg, #18181b 0%, #3f3f46 100%)';
}

function renderCards(emails, type) {
  if (!emails || emails.length === 0) return '<div class="empty">None detected in this period.</div>';
  return emails.map(e => `
    <div class="email-card ${type}">
      <div class="email-header">
        <div class="email-main-info">
          <div class="sender">${escapeHtml(e.sender || 'Unknown Sender')}</div>
          <div class="subject">${escapeHtml(e.subject || 'No Subject')}</div>
        </div>
        <div class="datetime">${escapeHtml(e.dateTime || '')}</div>
      </div>
      <div class="email-content">
        <div class="label">Key Insight / Why it matters</div>
        <div class="text">${escapeHtml(e.reason || e.summary || '')}</div>
        ${e.action ? `<div class="label action-lbl">Required Action / Status</div><div class="text">${escapeHtml(e.action)}</div>` : ''}
      </div>
    </div>
  `).join('');
}

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>InboxIQ Daily Report - ${escapeHtml(reportDate)}</title>
<style>
* { box-sizing: border-box; }
body { margin: 0; padding: 0; background: #f4f6f8; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1f2937; }
.container { max-width: 900px; margin: 30px auto; background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,0.06); }
.header { padding: 36px 40px; background: ${themeGradient}; color: #ffffff; }
.badge { display: inline-block; padding: 4px 12px; background: rgba(255,255,255,0.18); border-radius: 9999px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px; }
.header h1 { margin: 0; font-size: 26px; font-weight: 800; letter-spacing: -0.5px; }
.header-sub { margin-top: 6px; font-size: 14px; opacity: 0.85; }
.content { padding: 36px 40px; }
.section { margin-bottom: 32px; }
.section-title { font-size: 18px; font-weight: 700; margin: 0 0 14px 0; color: #111827; display: flex; align-items: center; gap: 8px; }
.summary-box { background: #f8fafc; border-left: 4px solid #3b82f6; border: 1px solid #e2e8f0; border-left-width: 4px; padding: 18px; border-radius: 8px; line-height: 1.65; font-size: 14px; }
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 24px; }
.stat-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 16px; text-align: center; }
.stat-val { font-size: 24px; font-weight: 800; color: #0f172a; }
.stat-lbl { font-size: 12px; font-weight: 600; color: #64748b; margin-top: 4px; text-transform: uppercase; }
.email-card { border: 1px solid #e2e8f0; border-radius: 10px; margin-bottom: 12px; overflow: hidden; background: #ffffff; }
.email-card.urgent { border-left: 5px solid #ef4444; }
.email-card.important { border-left: 5px solid #f59e0b; }
.email-card.replied { border-left: 5px solid #10b981; }
.email-card.other { border-left: 5px solid #94a3b8; }
.email-header { display: flex; justify-content: space-between; padding: 14px 16px; background: #f8fafc; border-bottom: 1px solid #f1f5f9; }
.sender { font-weight: 700; font-size: 14px; color: #0f172a; }
.subject { font-size: 14px; color: #334155; margin-top: 3px; font-weight: 500; }
.datetime { font-size: 12px; color: #64748b; }
.email-content { padding: 14px 16px; }
.label { font-size: 11px; font-weight: 700; text-transform: uppercase; color: #64748b; margin-bottom: 4px; }
.label.action-lbl { color: #2563eb; margin-top: 10px; }
.text { font-size: 13.5px; line-height: 1.55; color: #334155; }
.empty { padding: 16px; background: #f8fafc; border-radius: 8px; font-size: 13px; color: #64748b; font-style: italic; }
.action-list { margin: 0; padding-left: 20px; }
.action-list li { margin-bottom: 8px; font-size: 14px; color: #334155; line-height: 1.5; }
.footer { padding: 24px; border-top: 1px solid #e2e8f0; font-size: 12px; color: #94a3b8; text-align: center; }
@media(max-width: 640px) { .stats { grid-template-columns: repeat(2, 1fr); } .content { padding: 20px; } .header { padding: 24px 20px; } }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <div class="badge">${badgeTitle}</div>
    <h1>Daily Email Intelligence Report</h1>
    <div class="header-sub">Prepared for ${escapeHtml(userName)} | Date: ${escapeHtml(reportDate)}</div>
  </div>
  <div class="content">
    <div class="section">
      <div class="section-title">Executive Summary</div>
      <div class="summary-box">${escapeHtml(overallSummary)}</div>
    </div>
    <div class="section">
      <div class="section-title">24-Hour Overview</div>
      <div class="stats">
        <div class="stat-card"><div class="stat-val">${totalEmails}</div><div class="stat-lbl">Total Processed</div></div>
        <div class="stat-card"><div class="stat-val">${urgentEmails.length}</div><div class="stat-lbl">Urgent</div></div>
        <div class="stat-card"><div class="stat-val">${importantEmails.length}</div><div class="stat-lbl">Important</div></div>
        <div class="stat-card"><div class="stat-val">${repliedEmails.length}</div><div class="stat-lbl">Replied</div></div>
      </div>
    </div>
    <div class="section"><div class="section-title">🚨 Urgent Priority Emails</div>${renderCards(urgentEmails, 'urgent')}</div>
    <div class="section"><div class="section-title">⭐ High Importance</div>${renderCards(importantEmails, 'important')}</div>
    <div class="section"><div class="section-title">✅ Handled & Replied To</div>${renderCards(repliedEmails, 'replied')}</div>
    <div class="section"><div class="section-title">📋 Required Action Checklist</div>
      ${actionItems.length === 0 ? '<div class="empty">No pending action items identified.</div>' : `<ul class="action-list">${actionItems.map(a => `<li>${escapeHtml(a)}</li>`).join('')}</ul>`}
    </div>
    <div class="section"><div class="section-title">📁 General & Informational</div>${renderCards(otherEmails, 'other')}</div>
  </div>
  <div class="footer">Generated automatically by InboxIQ Email Intelligence Engine • Multi-Tenant SaaS Delivery</div>
</div>
</body>
</html>`;

const safeDate = String(reportDate).replace(/[^0-9-]/g, '');
const fileName = `InboxIQ-Report-${safeDate}.html`;

return [{
  json: {
    html,
    reportDate,
    fileName,
    recipientEmail: ctx.userEmail,
    totalEmails,
    overallSummary,
    executionId: ctx.executionId,
    userId: ctx.userId
  }
}];

